from pathlib import Path
from datetime import datetime,timezone
import ast,difflib,hashlib,json,subprocess
task=Path("reports/T0007");out=task/"review-r2-freeze"
def sha(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()
old=json.loads((task/"review-r1-freeze/audit.json").read_text())
last=json.loads((task/"review-r1/final-audit.json").read_text())
mutable={"README.md","docs/implementation_status.md","docs/handoffs/T0007-relation-dag.md","tests/test_dependency.py"}
for p,h in old["input_sha256"].items():
    if p not in mutable:assert sha(p)==h,p
for p,h in old["history_sha256"].items():assert sha(p)==h,p
for p,h in last["artifact_sha256"].items():
    if p not in mutable:assert sha(p)==h,p
assert subprocess.check_output(["git","rev-parse","HEAD"],text=True).strip()==old["head"]
before=(task/"review-r1-freeze/input-snapshot/tests/test_dependency.py").read_text()
after=Path("tests/test_dependency.py").read_text()
(out/"tests.diff").write_text("".join(difflib.unified_diff(before.splitlines(True),after.splitlines(True),fromfile="R1/tests/test_dependency.py",tofile="R2/tests/test_dependency.py")))
def functions(source):
    return {n.name:ast.dump(n,include_attributes=False) for n in ast.parse(source).body if isinstance(n,(ast.FunctionDef,ast.ClassDef))}
bf,af=functions(before),functions(after)
changed=[k for k in bf.keys()|af.keys() if bf.get(k)!=af.get(k)]
assert changed==["test_generator_outer_not_consumed"],changed
inputs=["src/kmesh/logic/dependency.py","tests/test_dependency.py","README.md","docs/implementation_status.md","docs/handoffs/T0007-relation-dag.md","reports/T0007/pi-r2-focused/provenance.md","reports/T0007/pi-r2-scripts/doc_check.py","reports/T0007/record_check.py"]
hashes={}
for p in inputs:
    dest=out/"input-snapshot"/p;dest.parent.mkdir(parents=True,exist_ok=True);dest.write_bytes(Path(p).read_bytes());hashes[p]=sha(p)
assert hashes[inputs[1]]=="722869ef49a4884d52c1423d3743d4802264bd55ebc7a84521f9433d74ba6313"
assert hashes[inputs[0]]==old["input_sha256"][inputs[0]]
records=[]
for d in sorted(task.glob("pi-r2*/record.json")):
    rec=json.loads(d.read_text())
    assert rec["exit_code"]==0 and rec["status"]=="finished",d
    assert rec["before"]["source_sha256"]==rec["after"]["source_sha256"],d
    for p,h in rec["before"]["source_sha256"].items():assert sha(p)==h,(d,p)
    for stream in ("stdout","stderr"):assert sha(d.parent/(stream+".txt"))==rec[stream+"_sha256"]
    records.append({"run":d.parent.name,**{k:rec[k] for k in ("argv","exit_code","elapsed_s","started_at_utc","finished_at_utc")}})
assert len(records)==3
history={str(p):sha(p) for p in Path("reports").rglob("*") if p.is_file() and "pytest-tmp" not in p.parts and "__pycache__" not in p.parts and not str(p).startswith("reports/T0007/review-r2")}
supplement=Path("/tmp/t7d3.json")
supplement_info={"path":str(supplement),"exists_at_review":supplement.is_file(),"limits":"Report content only; original invocation and environment not recorded by record_check."}
if supplement.is_file():
    report=json.loads(supplement.read_text())
    dest=out/"supplement/t7d3.json";dest.parent.mkdir(exist_ok=True);dest.write_bytes(supplement.read_bytes())
    supplement_info|={"copied_to":str(dest),"sha256":sha(supplement),"generated_at_utc":report.get("generated_at_utc"),"torch":report.get("packages",{}).get("torch"),"status":report.get("status"),"cuda":report.get("cuda")}
audit={"observed_at_utc":datetime.now(timezone.utc).isoformat(),"head":old["head"],"input_sha256":hashes,"history_sha256":history,"pi_r2_records":records,"changed_test_functions":changed,"previous_832_history_unchanged":True,"previous_review_artifacts_unchanged":True,"supplement":supplement_info}
(out/"audit.json").write_text(json.dumps(audit,ensure_ascii=False,indent=2)+"\n")
print("PASS: product frozen, only target test function changed, all three Pi R2 RUN hashes/outputs verified")
print(f"PASS: {len(history)} historical files frozen; old 832-file set and Codex review unchanged")
print("Supplement:",json.dumps(supplement_info,ensure_ascii=False))
